import math


def simulate_cart(sensor_frames, commands, checkpoint_count):
    if isinstance(checkpoint_count, bool) or not isinstance(checkpoint_count, int):
        raise TypeError("checkpoint_count must be an integer")
    if checkpoint_count < 0:
        raise ValueError("checkpoint_count must be non-negative")
    if not isinstance(sensor_frames, (list, tuple)) or not isinstance(commands, (list, tuple)):
        raise TypeError("frames and commands must be sequences")
    if len(sensor_frames) != len(commands):
        raise ValueError("frames and commands must have equal lengths")
    if checkpoint_count == 0:
        return {"alive": True, "steps": 0, "checkpoints": 0}

    checked = []
    for frame in sensor_frames:
        if not isinstance(frame, (list, tuple)) or len(frame) != 3:
            raise ValueError("each frame must contain three distances")
        row = []
        for value in frame:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("distances must be numeric")
            if not math.isfinite(value) or value < 0:
                raise ValueError("distances must be finite and non-negative")
            row.append(value)
        checked.append(row)
    if not all(isinstance(command, str) and command in {"L", "F", "R"} for command in commands):
        raise ValueError("invalid command")

    direction = {"L": 0, "F": 1, "R": 2}
    steps = 0
    checkpoints = 0
    for frame, command in zip(checked, commands):
        if frame[direction[command]] < 0:
            return {"alive": False, "steps": steps, "checkpoints": checkpoints}
        steps += 1
        checkpoints = min(checkpoint_count, steps // 3)
        if checkpoints == checkpoint_count:
            break
    return {"alive": True, "steps": steps, "checkpoints": checkpoints}

